drawing_name = #{drawingName}, file_format = #{fileFormat}, file_size = #{fileSize}, storage_path = #{storagePath}, preview_path = #{previewPath}, preview_status = #{previewStatus}, latest_version = #{latestVersion}, material_id = #{materialId},
WHERE id = #{id}
